Continuation c = new Continuation(40);
System.assertEquals(40, c.Timeout);
System.assertEquals(0, c.getRequests().size());
HttpRequest req = new HttpRequest();
req.setEndpoint('https://example.com');
req.setMethod('GET');
String label = c.addHttpRequest(req);
System.assertEquals(1, c.getRequests().size());
System.assert(c.getRequests().containsKey(label));

